int climb(int n) {
  final w = List<int>.filled(n + 1, 0);
  w[0] = 1;
  if (n >= 1) w[1] = 1;
  for (var i = 2; i <= n; i++) {
    w[i] = w[i - 1] + w[i - 2];
  }
  return w[n];
}

