int countWays(List<int> coins, int amount) {
  final ways = List<int>.filled(amount + 1, 0);
  ways[0] = 1;
  for (final c in coins) {
    for (var a = c; a <= amount; a++) {
      ways[a] += ways[a - c];
    }
  }
  return ways[amount];
}

