import 'dart:math';

int minPath(List<List<int>> g) {
  final r = g.length, c = g[0].length;
  final dp = List.generate(r, (_) => List.filled(c, 0));
  for (var i = 0; i < r; i++) {
    for (var j = 0; j < c; j++) {
      if (i == 0 && j == 0) {
        dp[i][j] = g[i][j];
      } else if (i == 0) {
        dp[i][j] = dp[i][j - 1] + g[i][j];
      } else if (j == 0) {
        dp[i][j] = dp[i - 1][j] + g[i][j];
      } else {
        dp[i][j] = g[i][j] + min(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }
  return dp[r - 1][c - 1];
}

void main() {
  print(minPath([[1, 2], [5, 1]]));
}
