import 'dart:math';

int knapsack(List<(int, int)> items, int cap) {
  final dp = List<int>.filled(cap + 1, 0);
  for (final (w, v) in items) {
    for (var c = cap; c >= w; c--) {
      dp[c] = max(dp[c], dp[c - w] + v);
    }
  }
  return dp[cap];
}

void main() {
  print(knapsack([(1, 1), (3, 4), (4, 5), (5, 7)], 7));
}
