import 'dart:math';

int rob(List<int> h) {
  var take = 0, skip = 0;
  for (final m in h) {
    final nt = skip + m;
    skip = max(take, skip);
    take = nt;
  }
  return max(take, skip);
}

void main() {
  print(rob([1, 2, 3, 1]));
  print(rob([2, 1, 1, 2]));
}
